begin;
create or replace function public.adjust_points(p_user uuid,p_semester uuid,p_points integer,p_request uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$ declare dep uuid;begin select department_id into dep from public.profiles where id=p_user;if not public.is_admin(dep) or length(p_reason)<5 then raise exception 'adjustment forbidden';end if;if not exists(select 1 from public.policies where approved and points_enabled) or not exists(select 1 from public.points_rules where approved) then raise exception 'points rules pending';end if;perform set_config('utr.reason',p_reason,true);insert into public.points_ledger(student_id,semester_id,activity,source_id,points,reason) values(p_user,p_semester,'administrative_adjustment',p_request,p_points,p_reason) on conflict do nothing;end; $$;
commit;
